const searchChatMessagesForViewer = `-- name: SearchChatMessagesForViewer :many
WITH q AS (SELECT websearch_to_tsquery('english', $2::text) AS tsq, $2::text AS qstr)
SELECT 'chat_message'::text AS entity_type, cm.id::text AS id, cm.room_id::text AS parent_id,
       COALESCE(NULLIF(cr.name, ''), 'Direct message')::text AS parent_title,
       COALESCE(NULLIF(cr.name, ''), 'Direct message')::text AS title,
       ts_headline('english', cm.body, q.tsq, 'MaxFragments=1, MaxWords=18, MinWords=5, ShortWord=3, HighlightAll=false, StartSel=<mark>, StopSel=</mark>')::text AS snippet,
       u.id::text AS author_id, u.username, u.display_name, u.avatar_url,
       cm.created_at,
       (ts_rank_cd(cm.search_vector, q.tsq) + COALESCE(similarity(cm.body, q.qstr), 0))::float8 AS rank,
       COUNT(*) OVER () AS total_count
FROM chat_messages cm
JOIN chat_room_members crm ON crm.room_id = cm.room_id AND crm.user_id = $1 AND crm.left_at IS NULL
JOIN chat_rooms cr ON cr.id = cm.room_id
JOIN users u ON cm.sender_id = u.id
CROSS JOIN q
WHERE cm.is_system = false
  AND cr.system_kind IS DISTINCT FROM 'watch_party'
  AND u.banned_at IS NULL AND u.locked_at IS NULL
  AND ($3::uuid = '00000000-0000-0000-0000-000000000000'::uuid OR cm.room_id = $3::uuid)
  AND (cm.search_vector @@ q.tsq OR cm.body % q.qstr)
ORDER BY rank DESC, cm.created_at DESC
LIMIT $4 OFFSET $5
`

type SearchChatMessagesForViewerParams struct {
	UserID  uuid.UUID
	Column2 string
	Column3 uuid.UUID
	Limit   int32
	Offset  int32
}

type SearchChatMessagesForViewerRow struct {
	EntityType  string
	ID          string
	ParentID    string
	ParentTitle string
	Title       string
	Snippet     string
	AuthorID    string
	Username    string
	DisplayName string
	AvatarUrl   string
	CreatedAt   time.Time
	Rank        float64
	TotalCount  int64
}

func (q *Queries) SearchChatMessagesForViewer(ctx context.Context, arg SearchChatMessagesForViewerParams) ([]SearchChatMessagesForViewerRow, error) {
	rows, err := q.db.QueryContext(ctx, searchChatMessagesForViewer,
		arg.UserID,
		arg.Column2,
		arg.Column3,
		arg.Limit,
		arg.Offset,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SearchChatMessagesForViewerRow{}
	for rows.Next() {
		var i SearchChatMessagesForViewerRow
		if err := rows.Scan(
			&i.EntityType,
			&i.ID,
			&i.ParentID,
			&i.ParentTitle,
			&i.Title,
			&i.Snippet,
			&i.AuthorID,
			&i.Username,
			&i.DisplayName,
			&i.AvatarUrl,
			&i.CreatedAt,
			&i.Rank,
			&i.TotalCount,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

